function notice(s){$('organizeStatus').textContent=s;}
$('clearPicked').onclick=()=>{picked.clear();render();};
$('movePicked').onclick=()=>{const ids=new Set(picked),count=records.filter(r=>ids.has(r.id)&&r.series!==targetSeries).length;if(!count){notice('選んだフィギュアはすでにこのシリーズです。');return;}checkpoint();records.forEach(r=>{if(ids.has(r.id)){r.series=targetSeries;if(r.series2===targetSeries)r.series2='';}});picked.clear();persist();render();notice(count+'体を「'+targetSeries+'」へ移動しました。');};
$('renameSeries').onclick=()=>{const name=$('seriesName').value.trim();if(!name||name===targetSeries)return;if(seriesNames().includes(name)){notice('同じ名前のシリーズがあります。移動機能でまとめてください。');return;}checkpoint();const from=targetSeries;records.forEach(r=>{if(r.series===from)r.series=name;if(r.series2===from)r.series2=name;});workshopMeta.series=workshopMeta.series.filter(x=>x!==from);workshopMeta.series.push(name);if($('series').value===from){$('series').append(new Option(name,name));$('series').value=name;}targetSeries=name;persist();render();notice('シリーズ名を変更しました。');};
$('createSeries').onclick=()=>{const name=$('seriesName').value.trim();if(!name)return;if(seriesNames().includes(name)){targetSeries=name;render();notice('既存のシリーズを開きました。');return;}checkpoint();workshopMeta.series.push(name);targetSeries=name;persist();render();notice('新しいシリーズを作成しました。');};
$('renameTagSelect').onchange=()=>{$('tagName').value=tagNames.get($('renameTagSelect').value)||'';renderTagOrganizer();};
$('renameTag').onclick=()=>{const id=$('renameTagSelect').value,name=$('tagName').value.trim();if(!id||!name||name===tagNames.get(id))return;checkpoint();workshopMeta.tagNames[id]=name;syncTagLabels();persist();render();notice('タグ名を変更しました。');};$('organizerUndo').onclick=undoWorkshop;

function getPath(obj,path){return path.split('.').reduce((v,k)=>v?.[k],obj);}
materialEditor=function(m,path,label){
 const kind=m.any?'any':m.id!==undefined?'id':m.tag!==undefined?'tag':m.attribute!==undefined?'attribute':m.rarity!==undefined?'rarity':'class';
 let body='';if(kind==='any')body='<p class="small">次のどれか1つを満たす素材</p>'+m.any.map((x,i)=>'<div>'+materialEditor(x,path+'.any.'+i,'候補'+(i+1))+'<button data-or-remove="'+path+'" data-index="'+i+'" '+(m.any.length<2?'disabled':'')+'>この候補を外す</button></div>').join('')+'<button data-or-add="'+path+'">＋ 選べる候補を追加</button>';
 else if(kind==='id'){const f=records.find(r=>r.id===m.id);body='<div class="materialPicker"><div class="materialPreview">'+(f?'<img src="'+esc(C.imageFor(f.id,D))+'" alt="'+esc(f.name)+'"><span>'+esc(f.name)+' · '+esc(f.id)+'</span>':'素材を選んでください')+'</div><label>素材を名前・IDで検索<input type="search" data-material-search="'+path+'" placeholder="名前を入力して候補を絞る"></label><label>フィギュアを選ぶ<select data-path="'+path+'.id" data-figure-select="'+path+'">'+options([['','素材を選択'],...records.map(r=>[r.id,r.name+' / '+r.id+' / '+classLabels[r.soulClass]])],m.id)+'</select></label></div>';}
 else {const choices=kind==='tag'?D.tags.map(t=>[t.id,tagNames.get(t.id)+' / '+t.id]):kind==='class'?C.classes.map(k=>[k,classLabels[k]]):[...new Set(records.map(r=>r[kind]))];if(m[kind]&&!choices.some(x=>(Array.isArray(x)?x[0]:x)===m[kind]))choices.push([m[kind],m[kind]+'（未登録）']);body=select(label,path+'.'+kind,m[kind]||'',[['','選択してください'],...choices]);}
 return '<div class="recipe materialCondition"><label>'+esc(label)+'の条件<select data-material-path="'+path+'">'+options([['id','フィギュアを選ぶ'],['tag','タグから指定'],['attribute','属性から指定'],['rarity','レア度から指定'],['class','段階から指定'],['any','いずれか（OR条件）']],kind)+'</select></label>'+body+'</div>';
};
const simpleMaterialEditor=materialEditor;materialEditor=function(m,path,label){if(!m.allTags&&!m.tagsAtLeast)return simpleMaterialEditor(m,path,label);const tags=m.allTags||m.tagsAtLeast.tags,key=m.allTags?'allTags':'tagsAtLeast.tags';return '<div class="recipe materialCondition"><strong>'+esc(label)+(m.allTags?'：すべてのタグを満たす':'：指定数以上のタグを満たす')+'</strong>'+(m.tagsAtLeast?input('必要なタグ数',path+'.tagsAtLeast.count',m.tagsAtLeast.count,'number'):'')+tags.map((t,i)=>select('タグ '+(i+1),path+'.'+key+'.'+i,t,D.tags.map(x=>[x.id,tagNames.get(x.id)||x.name]))).join('')+'</div>';};
const originalRecipes=recipesEditor;
