// Explicitly requested one-time cleanup, evaluated after the user's draft is restored.
let tagAuditBootReady=false;
let tagAuditState=clone(D.tagAudit||{version:1,completed:false,deleted:[]});
let tagAuditCatalog=clone(D.tags);
function tagAuditRefs(value,id){if(!value||typeof value!=='object')return false;return Object.entries(value).some(([key,v])=>(/tag/i.test(key)&&(v===id||Array.isArray(v)&&v.includes(id)))||tagAuditRefs(v,id));}
function tagAuditRows(){
 const names=new Map([...tagAuditCatalog,...D.tags].map(t=>[t.id,workshopMeta.tagNames[t.id]||t.name]));for(const r of records)for(const id of r.tags)if(!names.has(id))names.set(id,id);
 const deleted=new Set(tagAuditState.deleted.map(t=>t.id));
 return [...names].filter(([id])=>!deleted.has(id)).map(([id,name])=>{
 const members=records.filter(r=>r.tags.includes(id)),skill=records.filter(r=>{const passive={...r.summon.passive};delete passive.evolve;return tagAuditRefs(r.skill.plan,id)||tagAuditRefs(passive,id);}),fusion=records.filter(r=>tagAuditRefs(r.summon.recipes,id)||tagAuditRefs(r.summon.passive?.evolve,id));
 const text=records.filter(r=>[r.skill.description,...Object.values(r.skill.custom||{})].some(s=>typeof s==='string'&&s.includes(name)));
 return {id,name,count:members.length,members:members.map(r=>({id:r.id,name:r.name})),skill:skill.map(r=>({id:r.id,name:r.name})),fusion:fusion.map(r=>({id:r.id,name:r.name})),text:text.map(r=>({id:r.id,name:r.name}))};
 }).sort((a,b)=>b.count-a.count||a.id.localeCompare(b.id,'ja',{numeric:true}));
}
function tagAuditApplyCatalog(){const gone=new Set(tagAuditState.deleted.map(t=>t.id));D.tags=tagAuditCatalog.filter(t=>!gone.has(t.id));syncTagLabels();}
function tagAuditRestore(value){if(!value?.tagAudit)return;const a=value.tagAudit;if(a.version!==1||!Array.isArray(a.deleted))return;tagAuditState=clone(a);tagAuditApplyCatalog();}
const tagAuditEnvelope=C.envelope;C.envelope=(...args)=>({...tagAuditEnvelope(...args),tagAudit:clone(tagAuditState)});
const tagAuditImport=applyImport;applyImport=function(){const value=pendingImport?.value||pendingImport?.parsed?.value;if(!pendingImport)return;tagAuditImport();if(value?.tagAudit){tagAuditRestore(value);persist();render();}if(!tagAuditState.completed)runTagCleanup();tagAuditRender();};
function runTagCleanup(){
 if(tagAuditState.completed||pendingImport)return;
 const rows=tagAuditRows(),deleted=rows.filter(t=>t.count<=3);
 // Keep a complete recovery record; skill/recipe expressions are not broadened.
 tagAuditState={version:1,completed:true,at:new Date().toISOString(),deleted};
 const ids=new Set(deleted.map(t=>t.id));for(const r of records)r.tags=r.tags.filter(id=>!ids.has(id));
 tagAuditApplyCatalog();persist();render();tagAuditRender();
 saveMessage('タグ整理済み：所属0〜3体の'+deleted.length+'タグを削除。ランキングで確認できます。');
}
const tagAuditButton=document.createElement('button');tagAuditButton.id='tagRanking';tagAuditButton.textContent='タグランキング';document.querySelector('nav').append(tagAuditButton);
const tagAuditDialog=document.createElement('dialog');tagAuditDialog.id='tagAuditDialog';tagAuditDialog.innerHTML='<div class="dialogbar"><b>タグ人数ランキング・使用状況</b><button id="tagAuditClose">閉じる ×</button></div><div class="ioBody"><p>所属人数＝同じタグを持つフィギュアの種類数。スキル参照＝効果プラン・常時効果の直接参照、融合参照＝融合・条件進化の直接参照です。自由記述の言及は別欄で示します。</p><label>表示<select id="tagAuditFilter"><option value="all">人数が多い順・すべて</option><option value="noSkill">スキルから直接使われていない</option><option value="small">少人数（4〜10体）</option><option value="unreferenced">スキル・融合の直接参照が両方ない</option></select></label><p id="tagAuditSummary"></p><div class="tagAuditScroll"><table><thead><tr><th>順位</th><th>タグ</th><th>所属</th><th>スキル</th><th>融合</th><th>文章の言及</th></tr></thead><tbody id="tagAuditRows"></tbody></table></div><details><summary>削除済みタグと影響</summary><div id="tagAuditDeleted"></div></details><button id="tagAuditExport">集計JSONを保存</button></div>';
document.body.append(tagAuditDialog);
function tagAuditRender(){
 const rows=tagAuditRows(),f=$('tagAuditFilter').value,shown=rows.map((r,i)=>({...r,rank:i+1})).filter(r=>f==='noSkill'?!r.skill.length:f==='small'?r.count>=4&&r.count<=10:f==='unreferenced'?!r.skill.length&&!r.fusion.length:true);
 $('tagAuditSummary').textContent=rows.length+'タグ / 表示'+shown.length+'タグ / 削除済み'+tagAuditState.deleted.length+'タグ';
 const refs=(xs)=>xs.length?'<details><summary>'+xs.length+'体</summary>'+xs.map(r=>esc(r.name)+' / '+esc(r.id)).join('<br>')+'</details>':'0';
 $('tagAuditRows').innerHTML=shown.map(r=>'<tr><td>'+r.rank+'</td><td>'+esc(r.name)+'<small>'+esc(r.id)+'</small></td><td>'+refs(r.members)+'</td><td>'+refs(r.skill)+'</td><td>'+refs(r.fusion)+'</td><td>'+refs(r.text)+'</td></tr>').join('');
 $('tagAuditDeleted').innerHTML=tagAuditState.deleted.map(r=>'<p><b>'+esc(r.name)+'</b>（'+r.count+'体）'+(r.skill.length||r.fusion.length?'<br><strong class="warning">参照する条件が残っています。本体反映前に修正が必要です。</strong><br>'+[...r.skill,...r.fusion].map(x=>esc(x.name)+' / '+esc(x.id)).join('、'):'：スキル・融合の直接参照なし')+'</p>').join('')||'<p>削除記録なし</p>';
}
tagAuditButton.onclick=()=>{tagAuditRender();tagAuditDialog.showModal();};$('tagAuditClose').onclick=()=>tagAuditDialog.close();$('tagAuditFilter').onchange=tagAuditRender;$('tagAuditExport').onclick=()=>download('MOB-tag-ranking-'+stamp()+'.json',JSON.stringify({rows:tagAuditRows(),cleanup:tagAuditState},null,2));
window.Workshop.tagAudit=()=>({rows:tagAuditRows(),cleanup:clone(tagAuditState)});


const auditCheckpoint=checkpoint;checkpoint=function(){auditCheckpoint();history.at(-1).tagAudit=clone(tagAuditState);};
function renderTagOrganizer(){
 const id=$('renameTagSelect').value,q=$('tagMemberSearch').value.toLocaleLowerCase();
 const members=records.filter(r=>r.tags.includes(id)),shown=members.filter(r=>(r.name+' '+r.id).toLocaleLowerCase().includes(q));
 $('tagMembers').innerHTML='<p class="small">'+shown.length+' / '+members.length+'体・選択中 '+picked.size+'体</p>'+shown.map(r=>'<button class="seriesMember" data-edit="'+esc(r.id)+'"><img loading="lazy" src="'+esc(C.imageFor(r.id,D))+'" alt=""><span>'+esc(r.name)+'<small>'+esc(r.id)+'</small></span></button>').join('');
 for(const key of ['addPickedTag','removePickedTag'])$(key).disabled=!id||!picked.size;
 $('deleteTag').disabled=!id;$('deleteSeries').disabled=!targetSeries||targetSeries==='未分類';
}
$('tagMemberSearch').oninput=renderTagOrganizer;
const tagOrganizeButton=document.createElement('button');tagOrganizeButton.id='tagOrganizeToggle';tagOrganizeButton.textContent='タグ整理';document.querySelector('nav').append(tagOrganizeButton);
tagOrganizeButton.onclick=()=>{setOrganizing(true);$('tagOrganizer').open=true;$('tagOrganizer').scrollIntoView({block:'nearest'});};
function updatePickedTags(add){const id=$('renameTagSelect').value;if(!id||!picked.size)return;const affected=records.filter(r=>picked.has(r.id)&&(add?!r.tags.includes(id):r.tags.includes(id)));if(!affected.length){notice('変更対象はありません。');return;}checkpoint();for(const r of affected)r.tags=add?[...r.tags,id]:r.tags.filter(t=>t!==id);persist();render();notice(affected.length+'体のタグを'+(add?'追加':'解除')+'しました。');}
$('addPickedTag').onclick=()=>updatePickedTags(true);$('removePickedTag').onclick=()=>updatePickedTags(false);
$('deleteSeries').onclick=()=>{const name=targetSeries;if(!name||name==='未分類')return;checkpoint();let count=0;for(const r of records)if(C.seriesList(r).includes(name)){const remaining=C.seriesList(r).filter(x=>x!==name);r.series=remaining[0]||'未分類';r.series2='';count++;}workshopMeta.series=workshopMeta.series.filter(s=>s!==name);if($('series').value===name)$('series').value='';targetSeries='未分類';persist();render();notice('「'+name+'」を削除しました。'+count+'体から所属を外しました。他の所属は保持しています。1操作戻すで復元できます。');};
$('deleteTag').onclick=()=>{const id=$('renameTagSelect').value,row=tagAuditRows().find(r=>r.id===id);if(!row)return;checkpoint();tagAuditState.deleted.push({...row,manual:true,at:new Date().toISOString()});for(const r of records)r.tags=r.tags.filter(t=>t!==id);if($('tag').value===id)$('tag').value='';tagAuditApplyCatalog();persist();render();tagAuditRender();notice('「'+row.name+'」を削除しました。'+(row.skill.length||row.fusion.length?'スキル・融合条件の参照は残っています。ランキングの削除済み欄で対象を確認できます。':'')+'1操作戻すで復元できます。');};

document.querySelector('main').inert=true;$('openIO').disabled=true;$('openChanges').disabled=true;render();saveMessage('保存済み下書きを確認しています…');
(async()=>{try{let local;try{local=localStorage.getItem(STORAGE);}catch{}db=await Promise.race([openDB(),new Promise(r=>setTimeout(()=>r(null),1800))]);const storedSource=db?await dbGet('source'):null;if(storedSource){const newer=C.parseSource(storedSource);if(newer.extractedAt>D.extractedAt){refreshSource(newer);C.installWorkspace(newer.workshop);records=clone(D.records);}}const indexed=db?await dbGet('current'):null;const candidates=[local,indexed].filter(Boolean).map(t=>{try{return {text:t,p:C.parseImport(t,D)};}catch{return null;}}).filter(Boolean).sort((a,b)=>String(b.p.value.exportedAt).localeCompare(String(a.p.value.exportedAt)));if(candidates.length){const {p,text}=candidates[0];if(!p.conflict){restoreWorkshopMeta(p.value);tagAuditRestore(p.value);}if(p.conflict&&window.MPB_MIGRATION_BASES.some(b=>b.sourceHash===p.value.sourceHash)){const base=window.MPB_MIGRATION_BASES.find(b=>b.sourceHash===p.value.sourceHash),delta=C.changes(p.value.records,{...D,records:base.records});const rebased={...p,conflict:false,unbased:false,patches:delta,value:{...p.value,workshopBase:base.workshop}};const merged=C.mergeImport(rebased,records,D.workshop);records=merged.records;C.installWorkspace(merged.workshop);restoreWorkshopMeta(p.value);tagAuditRestore(p.value);orphans=[...(p.value.unresolvedImports||[]),...merged.conflicts,...merged.unknown];persist();render();saveMessage('最新版へ更新。保存済みの編集を引き継ぎました。'+(merged.conflicts.length?'後から変更した項目 '+merged.conflicts.length+'件は保存・出力で確認できます。':'追加の競合はありません。'));}else if(p.conflict){orphans.push({reason:'unapplied-source-conflict',payload:p.value});stageImport(text);saveMessage('別版の下書きがあります。「保存・出力」で競合を確認',true);}else if(!unsaved){const restored=C.mergeImport(p,records);records=restored.records;C.installWorkspace(restored.workshop);orphans=[...(p.value.unresolvedImports||[]),...restored.conflicts,...restored.unknown];render();saveMessage('自動下書きを復元しました');}}else if(local||indexed)saveMessage('保存データを復元できません。バックアップ／JSONを確認してください',true);else saveMessage('元データを読み込みました');if(candidates.length||(!local&&!indexed))tagAuditBootReady=true;}catch(e){saveMessage('下書き復元を確認できません。JSONまたはバックアップを確認してください',true);}finally{if(tagAuditBootReady)runTagCleanup();document.querySelector('main').inert=false;$('openIO').disabled=false;$('openChanges').disabled=false;}})();

